'use strict';
const KEY='contextseal-v1';
let data={agreements:[],packets:[]};
try{const d=JSON.parse(localStorage.getItem(KEY));if(d&&Array.isArray(d.agreements)&&Array.isArray(d.packets))data=d;}catch{message('Saved drafts could not be loaded. You can create a new draft.');}
function message(s){document.getElementById('notice').textContent=s;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));document.dispatchEvent?.(new Event('contextseal:drafts-changed'));return true;}catch{message('Browser storage is unavailable. Export your drafts before leaving.');return false;}}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function show(id){document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('hidden',p.id!==id));document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.panel===id));render();}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>show(b.dataset.panel)));
function download(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function validUrl(v){try{return new URL(v).protocol==='https:';}catch{return false;}}
function render(){const sel=document.getElementById('agreement-select');const old=sel.value;sel.innerHTML='<option value="">Choose an agreement draft</option>'+data.agreements.map(a=>'<option value="'+escapeHtml(a.id)+'">'+escapeHtml(a.title)+'</option>').join('');sel.value=old;const list=document.getElementById('record-list');if(!data.agreements.length){list.innerHTML='<div class="empty">No drafts yet. Create an editing agreement, then attach an evidence packet. Everything stays in this browser until you export it.</div>';return;}list.innerHTML=data.agreements.map(a=>{const packets=data.packets.filter(p=>p.agreementId===a.id);return '<article class="record"><span class="tag">UNSIGNED DRAFT · '+packets.length+' EVIDENCE PACKET'+(packets.length===1?'':'S')+'</span><h4>'+escapeHtml(a.title)+'</h4><p>'+escapeHtml(a.creator)+' → '+escapeHtml(a.brand)+' · '+escapeHtml(a.channel)+' · Ends '+escapeHtml(a.expires)+'</p><p>'+escapeHtml(a.rules)+'</p><div class="record-actions"><button class="text-button" data-export="'+escapeHtml(a.id)+'">Export review bundle ↓</button><button class="text-button" data-delete="'+escapeHtml(a.id)+'">Delete draft</button></div></article>';}).join('');list.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{const a=data.agreements.find(x=>x.id===b.dataset.export);download({version:1,status:'UNSIGNED_DRAFT',networkReview:'NOT_SUBMITTED',agreement:a,evidence:data.packets.filter(x=>x.agreementId===a.id)},'contextseal-review-'+a.id+'.json');});list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this draft and its evidence packets from this browser?'))return;data.agreements=data.agreements.filter(a=>a.id!==b.dataset.delete);data.packets=data.packets.filter(p=>p.agreementId!==b.dataset.delete);persist();render();});}
document.getElementById('agreement-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!validUrl(f.get('originalUrl'))){message('Use an HTTPS link for the original content.');return;}if(f.get('expires')<new Date().toLocaleDateString('en-CA')){message('Choose today or a future usage end date.');return;}const a={id:crypto.randomUUID(),title:f.get('title').trim(),creator:f.get('creator').trim(),brand:f.get('brand').trim(),channel:f.get('channel'),expires:f.get('expires'),originalUrl:f.get('originalUrl'),rules:f.get('rules').trim(),paidAds:f.has('paidAds'),attribution:f.has('attribution'),createdAt:new Date().toISOString(),status:'UNSIGNED_DRAFT'};if(!a.title||!a.creator||!a.brand||!a.rules){message('Fill in the title, both names and editing rules.');return;}data.agreements.push(a);const saved=persist();show('evidence');document.getElementById('agreement-select').value=a.id;if(saved)message('Agreement draft saved. Add the original and edited evidence next.');};
document.getElementById('evidence-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(!data.agreements.some(a=>a.id===f.get('agreementId'))){message('Choose a saved agreement first.');return;}if(!validUrl(f.get('editedUrl'))){message('Use an HTTPS link for the edited content.');return;}const payload={agreementId:f.get('agreementId'),originalText:f.get('originalText').trim(),editedText:f.get('editedText').trim(),editedUrl:f.get('editedUrl'),concern:f.get('concern').trim()};if(!payload.originalText||!payload.editedText||!payload.concern){message('Add both transcripts and describe the change.');return;}const bytes=new TextEncoder().encode(JSON.stringify(payload));let digest;try{digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');}catch{message('This browser cannot calculate the evidence hash. Use a secure browser to save the packet.');return;}data.packets.push({...payload,id:crypto.randomUUID(),createdAt:new Date().toISOString(),payloadSha256:digest,verification:'USER_SUBMITTED_NOT_VERIFIED',networkReview:'NOT_SUBMITTED'});const saved=persist();e.target.reset();show('records');if(saved)message('Evidence packet saved with a SHA-256 content hash. Export the bundle from your draft register.');};
document.getElementById('export-all').onclick=()=>download({version:1,networkReview:'NOT_SUBMITTED',...data},'contextseal-drafts.json');
document.getElementById('example').onclick=()=>{show('agreement');const form=document.getElementById('agreement-form');const values={title:'Example — keeping a product review in context',creator:'Example creator',brand:'Example brand',channel:'X',originalUrl:'https://example.com/original-review',rules:'Preserve every risk warning and statement of uncertainty. Do not imply a guarantee or unconditional endorsement. Captions and shorter clips are allowed only if the original meaning is preserved.'};Object.entries(values).forEach(([k,v])=>form.elements[k].value=v);const d=new Date();d.setDate(d.getDate()+30);form.elements.expires.value=d.toISOString().slice(0,10);document.getElementById('workspace').scrollIntoView({behavior:'smooth'});message('Illustrative example loaded. Replace the example links and names before using it.');};
render();
